--
-- Create procedure `Proc_User_GetById`
--
CREATE PROCEDURE Proc_User_GetById (IN `@Id` char(36))
SQL SECURITY INVOKER
COMMENT 'lấy user theo id'
BEGIN
  SELECT
    u.UserId,
    u.UserCode,
    u.UserName,
    u.Password,
    u.Email,
    u.AddressID,
    u.CreatedDate,
    u.CreatedBy,
    u.ModifiedBy,
    u.ModifiedDate,
    RoleType,
    RoleName
  FROM user u
    LEFT JOIN `role` r
      ON u.RoleId = r.RoleId
  WHERE UserID = `@Id`;
END
$$

