--
CREATE TABLE inventory (
  InventoryId char(36) NOT NULL DEFAULT '' COMMENT 'Định danh hàng hóa',
  InventoryName varchar(100) NOT NULL DEFAULT '' COMMENT 'Tên hàng hóa',
  SKUCode varchar(50) NOT NULL DEFAULT '' COMMENT 'Mã hàng hóa',
  SKUCodeCustom varchar(50) NOT NULL DEFAULT '',
  Barcode varchar(255) DEFAULT NULL COMMENT 'Mã vạch',
  CostPrice decimal(18, 4) DEFAULT NULL COMMENT 'Giá mua',
  UnitPrice decimal(18, 4) DEFAULT NULL COMMENT 'Giá bán',
  Color varchar(50) DEFAULT NULL COMMENT 'Màu',
  ColorCode varchar(50) DEFAULT NULL COMMENT 'Mã màu',
  Size varchar(50) DEFAULT NULL COMMENT 'Size',
  SizeCode varchar(50) DEFAULT NULL COMMENT 'Mã Size',
  Description varchar(255) DEFAULT NULL COMMENT 'Mô tả',
  PictureId char(36) DEFAULT NULL COMMENT 'Ảnh',
  IsActive tinyint(1) NOT NULL COMMENT 'Trạng thái kinh doanh',
  IsShowMenu tinyint(1) NOT NULL COMMENT 'Hiển thị trên menu',
  ParentId char(36) DEFAULT NULL COMMENT 'Id của hàng hóa cha',
  ItemCategoryId char(36) DEFAULT NULL COMMENT 'Khóa phụ của nhóm hàng hóa',
  UnitId char(36) DEFAULT NULL COMMENT 'Khóa phụ của đơn vị tính',
  CreatedDate datetime DEFAULT NULL COMMENT 'Ngày tạo',
  CreatedBy varchar(255) DEFAULT NULL COMMENT 'Người tạo',
  ModifiedBy varchar(255) DEFAULT NULL COMMENT 'Người sửa',
  ModifiedDate datetime DEFAULT NULL COMMENT 'Ngày sửa',
  AvgUnitPrice decimal(18, 4) DEFAULT NULL COMMENT 'Trung bình giá bán',
  AvgCostPrice decimal(18, 4) DEFAULT NULL COMMENT 'Trung bình giá nhập',
  PRIMARY KEY (InventoryId)
)
ENGINE = INNODB,
AVG_ROW_LENGTH = 273,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
COMMENT = 'Bảng hàng hóa';

