COMMENT 'Proc set null cho mã vạch'
BEGIN
  UPDATE inventory i
  SET i.Barcode = NULL
  WHERE FIND_IN_SET(i.Barcode, `@ListBarcodes`)
  AND i.ParentId IS NOT NULL;
END
$$

