    VALUES (`@InventoryId`, `@InventoryName`, `@SKUCode`, `@SKUCodeCustom`, `@Barcode`, `@CostPrice`, `@UnitPrice`, `@AvgUnitPrice`, `@AvgCostPrice`, `@Color`, `@ColorCode`, `@Size`, `@SizeCode`, `@Description`, `@PictureId`, `@IsActive`, `@IsShowMenu`, `@ParentId`, `@ItemCategoryId`, `@UnitId`, `@CreatedDate`, `@CreatedBy`);
END
