CREATE PROCEDURE Proc_Inventory_GetByIds (IN `@Ids` text)
SQL SECURITY INVOKER
COMMENT 'lấy danh sách hàng hóa theo chuỗi ids'
BEGIN
  -- lấy danh sách theo chuỗi ids
  SELECT
    vi.InventoryId,
    vi.InventoryName,
    vi.SKUCode,
    vi.SKUCodeCustom,
    vi.Barcode,
    vi.CostPrice,
    vi.UnitPrice,
    vi.Color,
    vi.ColorCode,
    vi.Size,
    vi.SizeCode,
    vi.Description,
    vi.PictureName,
    vi.PictureId,
    vi.IsActive,
    vi.IsShowMenu,
    vi.ParentId,
    vi.ItemCategoryId,
    vi.UnitId,
    vi.ItemCategoryName,
    vi.UnitName,
    vi.AvgUnitPrice,
    vi.AvgCostPrice
  FROM view_inventory vi
  WHERE FIND_IN_SET(vi.InventoryId, `@Ids`) > 0;
END
$$

