--
-- Create procedure `Proc_Filter`
--
CREATE PROCEDURE Proc_Filter (IN `@QueryLimit` text, OUT `@TotalRecords` int, IN `@QueryWhere` text, IN `@QueryOrder` text, IN `@TableName` varchar(255), IN `@QueryCode` text)
SQL SECURITY INVOKER
COMMENT 'Proc phân trang tìm kiếm lọc'
BEGIN
  SET @query = CONCAT('Select SQL_CALC_FOUND_ROWS *', `@QueryCode`, ' from view_', `@TableName`, ' as view ', `@QueryWhere`, `@QueryOrder`, `@QueryLimit`);
  PREPARE stmt FROM @query;
  EXECUTE stmt;
  DEALLOCATE PREPARE stmt;

  SELECT
    FOUND_ROWS() INTO `@TotalRecords`;
END
$$

--
-- Create procedure `Proc_Excute`
--
CREATE PROCEDURE Proc_Excute (IN `@QueryString` text)
SQL SECURITY INVOKER
COMMENT 'Proc để chạy truy vấn'
BEGIN
  SET @query = `@QueryString`;
  PREPARE stmt FROM @query;
  EXECUTE stmt;
  DEALLOCATE PREPARE stmt;
END
$$

DELIMITER ;

